import app from 'flarum/admin/app';
/**
 * Estado compartilhado entre a linha de status e a aba de atividade; uma
 * falha vira `error` para a UI mostrar inline, sem o modal global do core.
 */
export default class StatusState {
  data = null;
  loading = false;
  error = false;
  timer = null;
  load() {
    if (this.loading) return Promise.resolve();
    this.loading = true;
    this.error = false;
    return app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/mail-reply/status',
      errorHandler: () => {}
    }).then(data => {
      this.data = data;
    }, () => {
      this.error = true;
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }

  /**
   * Agrupa recargas disparadas por gravações em sequência numa só.
   */
  reloadSoon() {
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => {
      this.timer = null;
      this.load();
    }, 400);
  }
}
flarum.reg.add('ramon-mail-reply', 'admin/utils/StatusState', StatusState);