import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import humanTime from 'flarum/common/helpers/humanTime';
import { t, ts } from '../utils/trans';
import { missingFor } from '../types';
const STALE_FETCH_SECONDS = 600;

/**
 * Linha compacta de saúde do modo salvo: recebendo, precisando de atenção ou
 * desligado, com o que ainda falta configurar.
 */
export default class StatusLine extends Component {
  view() {
    const {
      state
    } = this.attrs;
    const data = state.data;
    if (!data) {
      return m("div", {
        className: "MailReplyAdmin-status",
        "data-tone": "off",
        role: state.error ? 'alert' : undefined
      }, state.error ? m('[', null, m("span", {
        className: "MailReplyAdmin-status-main"
      }, t('status_error')), m(Button, {
        className: "Button Button--text",
        icon: "fas fa-redo",
        onclick: () => state.load()
      }, t('status_retry'))) : m(LoadingIndicator, {
        size: "small",
        display: "inline"
      }));
    }
    const missing = missingFor(data);
    const [tone, headline] = this.health(data, missing.length);
    return m("div", {
      className: "MailReplyAdmin-status",
      "data-tone": tone
    }, m("span", {
      className: "MailReplyAdmin-status-dot",
      "aria-hidden": "true"
    }), m("div", {
      className: "MailReplyAdmin-status-main"
    }, m("strong", null, t(headline)), m("span", {
      className: "MailReplyAdmin-status-detail"
    }, this.detail(data)), missing.length ? m("ul", {
      className: "MailReplyAdmin-status-missing"
    }, m("li", {
      className: "MailReplyAdmin-status-missingLabel"
    }, t('status_missing')), missing.map(key => m("li", {
      key: key
    }, t('check_' + key)))) : null), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: 'fas fa-sync-alt' + (state.loading ? ' fa-spin' : ''),
      "aria-label": ts('status_refresh'),
      title: ts('status_refresh'),
      disabled: state.loading,
      onclick: () => state.load()
    }));
  }

  /**
   * Classifica a saúde do modo salvo: desligado, setup incompleto, poller
   * parado ou sem coleta recente, ou recebendo normalmente.
   */
  health(data, missing) {
    if (data.mode === 'disabled') return ['off', 'health_off'];
    if (missing > 0) return ['warn', 'health_setup'];
    if (data.mode === 'imap') {
      const last = data.polling.last_fetch;
      const stale = !last || Date.now() / 1000 - last.at > STALE_FETCH_SECONDS;
      const loopDown = data.polling.queue === 'async' && !data.polling.loop_alive;
      if (loopDown || stale) return ['warn', 'health_poller'];
    }
    return ['ok', 'health_ok'];
  }
  detail(data) {
    if (data.mode === 'disabled') return t('polling_disabled');
    if (data.mode === 'webhook') {
      return t('polling_webhook', {
        url: m("code", null, app.forum.attribute('apiUrl') + '/mail-reply/inbound')
      });
    }
    const {
      queue,
      loop_alive,
      last_fetch
    } = data.polling;
    const how = queue === 'sync' ? t('polling_scheduler', {
      code: m("code", null)
    }) : loop_alive ? t('polling_loop') : t('polling_loop_down', {
      code: m("code", null)
    });
    return [how, ' ', last_fetch ? t('last_fetch', {
      ago: humanTime(new Date(last_fetch.at * 1000)),
      processed: last_fetch.processed,
      failed: last_fetch.failed,
      skipped: last_fetch.skipped
    }) : t('last_fetch_never')];
  }
}
flarum.reg.add('ramon-mail-reply', 'admin/components/StatusLine', StatusLine);