import Component from 'flarum/common/Component';
import Switch from 'flarum/common/components/Switch';
import { getBool, saveSetting } from '../utils/settings';
/**
 * Switch que grava na hora como '1'/'0'.
 */
export default class AdminToggle extends Component {
  view() {
    const {
      setting,
      label,
      help
    } = this.attrs;
    return m("div", {
      className: "Form-group MailReplyAdmin-toggle"
    }, m(Switch, {
      state: getBool(setting),
      onchange: checked => saveSetting(setting, checked ? '1' : '0')
    }, label), help ? m("p", {
      className: "helpText"
    }, help) : null);
  }
}
flarum.reg.add('ramon-mail-reply', 'admin/components/AdminToggle', AdminToggle);